async function updateCompanyInfrastructure(companyId, entity) {
  try {
    if (!entity.id) {
      throw new Error('Entity ID is required for updates');
    }

    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'updateCompanyInfrastructure',
        companyId: companyId,
        entity: entity
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to update infrastructure entity');
    }

    return {
      success: true,
      entityId: entity.id,
      companyId: companyId,
      message: `Updated infrastructure entity '${entity.name || entity.id}' in company ${companyId}`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
